close(amountPaise: number): void {
  if (this.state !== 'open') return;
  if (!validatePlate(this.plate)) {
    this.state = 'disputed';
    return;
  }
  if (this.flags.isEnabled('charge-on-close')) {
    this.ledger.post(this.id, amountPaise);
  }
  this.closedAt = Date.now();
  this.state = 'closed';
}

export function plateChecksum(text: string): number {
  let sum = 0;
  for (const ch of text) sum = (sum * 31 + ch.charCodeAt(0)) % 97;
  return sum;
}

export interface Dispute {
  id: string;
  sessionId: string;
  reason: 'wrong-plate' | 'double-charge' | 'wrong-class' | 'other';
  status: DisputeStatus;
  openedAt: number;
  resolvedAt?: number;
}

it('charges a valid plate on close', () => {
  const ledger = new Ledger();
  const s = new TollSession('s1', { text: 'KA01AB1234', region: 'KA' }, ledger, new FeatureFlags());
  s.close(5500);
  expect(s.state).toBe('closed');
  expect(ledger.total()).toBe(5500);
});

it('marks an invalid plate disputed and never charges', () => {
  const ledger = new Ledger();
  const s = new TollSession('s2', { text: 'BAD', region: 'KA' }, ledger, new FeatureFlags());
  s.close(5500);
  expect(s.state).toBe('disputed');
  expect(ledger.total()).toBe(0);
});

export function normalizePlate(raw: string): string {
  return raw.replace(/[\s-]/g, '').toUpperCase();
}

export function validatePlate(plate: Plate): boolean {
  if (!PLATE_RE.test(plate.text)) return false;
  if (plate.checksum === undefined) return true;
  return plateChecksum(plate.text) === plate.checksum;
}

constructor(
  readonly id: string,
  readonly plate: Plate,
  private readonly ledger: Ledger,
  private readonly flags: FeatureFlags,
) {}
